import { TranslationCards } from '@vocably/model';
import { getSeoPageSlug, SeoLanguagePair } from '@vocably/model-operations';

// packages/www/seo/search-data/<pair>.json maps every word of the pair to its
// precomputed translation cards (generated by scripts/build-seo-search-data.mts).
// Terraform uploads the files to the SEO bucket under this key.
export const getSearchDataKey = (pair: string) => `search-data/${pair}.json`;

export type SeoPage = {
  word: string;
  translationCards: TranslationCards;
};

/**
 * Slugs are lossy, so pages are looked up by slug. When two words share a
 * slug ("brick maker", "brick-maker") the last one wins, as it did when the
 * pages were files overwritten in this order.
 */
export const buildPageIndex = (
  searchData: unknown,
  { sourceLanguage }: SeoLanguagePair
): Map<string, SeoPage> => {
  if (
    typeof searchData !== 'object' ||
    searchData === null ||
    Array.isArray(searchData)
  ) {
    throw new Error('The search data must be an object of translation cards');
  }

  const index = new Map<string, SeoPage>();

  for (const [word, translationCards] of Object.entries(searchData)) {
    if (!Array.isArray(translationCards?.items)) {
      continue;
    }

    index.set(getSeoPageSlug(word, sourceLanguage), {
      word,
      translationCards,
    });
  }

  return index;
};
